		ruleEntityType
		| rulePrimitiveTypeCS
		| ruleEnumEntity
		| ruleCollectionTypeCS
	);

// Rule Invariance
ruleInvariance:
	'inv' ruleSimpleNameCS ':' (
		'{' ruleOCLExpressionCS '}'
		| ruleOCLExpressionCS
