	('RequirementsModel::' ruleSimpleNameCS)? (
		'@Description(' RULE_DOUBLE_QUOTED_STRING ')'
	)? ruleUseCaseModel ruleDomainModel;

// Rule Interaction
ruleInteraction:
	'Interaction' ruleSimpleNameCS '{' '[Participants:' RULE_ID* ']' ruleMessage* ruleExecution*
		ruleCombinedFragment* ruleAbstractEnd* '}';

// Rule Message
ruleMessage: ( ruleCallMessage | ruleReturnMessage);

// Rule CallMessage
ruleCallMessage:
	'CallMessage::' ruleSimpleNameCS '(' RULE_ID RULE_ID '->' RULE_ID ')';

// Rule ReturnMessage
ruleReturnMessage:
	'ReturnMessage::' ruleSimpleNameCS '(' RULE_ID '->' RULE_ID RULE_ID ')';

// Rule Execution
ruleExecution:
	'Execution::' ruleSimpleNameCS '(' RULE_ID RULE_ID RULE_ID ')';

// Rule CombinedFragment
ruleCombinedFragment:
	'CombinedFragment::' ruleSimpleNameCS '->' ruleOperator '{' '[Participants:' RULE_ID* ']'
		RULE_ID '->' RULE_ID ruleOperand* '}';

// Rule Operator
ruleOperator: ( 'loop' | 'alt' | 'option');

// Rule Operand
ruleOperand:
	'Operand::' ruleSimpleNameCS '(' RULE_ID RULE_ID ')';

// Rule AbstractEnd
ruleAbstractEnd: ( ruleMixEnd | ruleMixOpAndCFEnd);

// Rule MixEnd
ruleMixEnd: ( ruleExecutionEnd | ruleMessageEnd);

// Rule MixOpAndCFEnd
ruleMixOpAndCFEnd: ( ruleCombinedFragmentEnd | ruleOperandEnd);

// Rule MessageEnd
ruleMessageEnd:
	'MessageEnd::' ruleSimpleNameCS '(' RULE_ID RULE_ID ')';

// Rule ExecutionEnd
ruleExecutionEnd:
	'ExecutionEnd::' ruleSimpleNameCS '(' RULE_ID RULE_ID ')';

// Rule CombinedFragmentEnd
ruleCombinedFragmentEnd:
	'CombinedFragmentEnd::' ruleSimpleNameCS '(' RULE_ID ')';

// Rule OperandEnd
ruleOperandEnd: 'OperandEnd::' ruleSimpleNameCS '(' RULE_ID ')';

// Rule DomainModel
ruleDomainModel:
	'DomainModel' ruleSimpleNameCS (
		'(' RULE_DOUBLE_QUOTED_STRING ')'
	)? '{' ruleEntity* '}';

// Rule UseCaseModel
ruleUseCaseModel:
	'UseCaseModel' ruleSimpleNameCS (
		'(' RULE_DOUBLE_QUOTED_STRING ')'
	)? '{' ruleUC* ruleActor* ruleInteraction* ruleService* ruleContract* '}';

// Rule Actor
ruleActor:
	'Actor' ruleSimpleNameCS ('(' RULE_DOUBLE_QUOTED_STRING ')')? (
		'extends' RULE_ID
	)? '{' ('@Description(' RULE_DOUBLE_QUOTED_STRING ')')? RULE_ID* '}';

// Rule UC
ruleUC:
	'UC' '::' ruleSimpleNameCS '('? RULE_DOUBLE_QUOTED_STRING? ')'? (
		ruleUSECASE_RELATION RULE_ID (',' RULE_ID)*
	)? ('definedBySSD' '(' RULE_ID ( ',' RULE_ID)* ')')? (
		'relatedService' '(' RULE_ID (',' RULE_ID)* ')'
	)? ('@Description(' RULE_DOUBLE_QUOTED_STRING ')')?;

// Rule Service
ruleService:
	'Service' ruleSimpleNameCS '{' (
		'@Description(' RULE_DOUBLE_QUOTED_STRING ')'
	)? ('[Operation]' ruleOperation*)? (
		'[TempProperty]' ruleAttribute*
	)? ('[WorkFlow]' RULE_ID*)? ('[INV]' ruleInvariance*)? '}';

// Rule Participant
ruleParticipant: ( ruleActor | ruleService);

// Rule Partition
rulePartition: RULE_ID '{' ruleWorkflowExp* '}';

// Rule WorkflowExp
ruleWorkflowExp:
	(
		ruleSimpleOperation
		| ruleComplexOpeartion
		| ruleInitalNode
		| ruleActivityFinal
		| ruleForkNode
		| ruleJoinNode
		| rulePartitionAction
	);

// Rule PartitionAction
rulePartitionAction: '->' RULE_ID ':' RULE_ID;

// Rule ActivityFinal
ruleActivityFinal: 'ActivityFinal';

// Rule InitalNode
ruleInitalNode: 'ActivityStart';

// Rule ForkNode
ruleForkNode: 'ForkNode' '->' '(' RULE_ID+ ')';

// Rule JoinNode
ruleJoinNode: '(' RULE_ID+ ')' '->' 'JoinNode';

// Rule ComplexOpeartion
ruleComplexOpeartion: ( ruleLoopExp | ruleSwitchExp);

// Rule SimpleOperation
ruleSimpleOperation: RULE_ID;

// Rule LoopExp
ruleLoopExp:
	'Loop' '->' ruleSimpleNameCS '{' ruleWorkflowExp* '}';

// Rule SwitchExp
ruleSwitchExp:
	'Switch' '->' ruleSimpleNameCS '{' ruleSwitchCase* ruleSwitchDefault? '}';

// Rule SwitchCase
ruleSwitchCase:
	'case:' ruleSimpleNameCS '->' ruleSimpleOperation;

// Rule SwitchDefault
ruleSwitchDefault: 'default:' ruleSimpleOperation;

// Rule Operation
ruleOperation:
	ruleOperationName '(' ruleParameter? (',' ruleParameter)* ')' (
		':' ruleTypeCS
	)?;

// Rule OperationName
ruleOperationName: ruleSimpleNameCS;

// Rule Parameter
ruleParameter: ruleParametersName ( ':' ruleTypeCS)?;

// Rule ParametersName
ruleParametersName: ruleSimpleNameCS;

// Rule Entity
ruleEntity:
	'@AutoCRUD'? 'Entity' ruleSimpleNameCS ('extends' RULE_ID)? '{' (
		'@Description(' RULE_DOUBLE_QUOTED_STRING ')'
	)? ruleAttribute* ('[Refer]' ruleReference*)? (
		'[INV]' ruleInvariance*
	)? '}';

// Rule Attribute
ruleAttribute: ruleSimpleNameCS ':' ruleTypeCS '*'?;

// Rule Reference
ruleReference:
	ruleSimpleNameCS ':' RULE_ID '*'? '!'? '@-'? '*-'? ruleAssociationTypeCS;

// Rule TypeCS
ruleTypeCS:
	(
		ruleEntityType
		| rulePrimitiveTypeCS
		| ruleEnumEntity
		| ruleCollectionTypeCS
	);

// Rule Invariance
ruleInvariance:
	'inv' ruleSimpleNameCS ':' (
		'{' ruleOCLExpressionCS '}'
		| ruleOCLExpressionCS
	) 'ASSOCINV'?;

// Rule EntityType
ruleEntityType: RULE_ID;

// Rule EnumEntity
ruleEnumEntity:
	ruleSimpleNameCS '[' ruleEnumItem ('|' ruleEnumItem)* ']';

// Rule EnumItem
ruleEnumItem: RULE_ID;

// Rule USECASE_RELATION
ruleUSECASE_RELATION: ( 'include' | 'extend');

// Rule Contract
ruleContract:
	'Contract' RULE_ID '::' ruleOperation '{' ruleDefinition? rulePrecondition rulePostcondition '}'
		;

// Rule Definition
ruleDefinition:
	'definition' ':' ruleVariableDeclarationCS (
		',' ruleVariableDeclarationCS
	)*;

// Rule Precondition
rulePrecondition:
	'precondition' ':' (
		ruleOCLExpressionCS
		| '{' ruleOCLExpressionCS '}'
	);

// Rule Postcondition
rulePostcondition:
	'postcondition' ':' (
		ruleOCLExpressionCS
		| '{' ruleOCLExpressionCS '}'
	);

// Rule OCLExpressionCS
ruleOCLExpressionCS:
	(
		ruleLiteralExpCS
		| ruleLetExpCS
		| ruleIfExpCS
		| ruleLogicFormulaExpCS
		| ruleNestedExpCS
	);

// Rule NestedExpCS
ruleNestedExpCS: '(' ruleOCLExpressionCS ')';

// Rule LogicFormulaExpCS
ruleLogicFormulaExpCS:
	ruleAtomicExpression (
		('and' | 'or') (
			ruleAtomicExpression
			| ruleIfExpCS
			| ruleNestedExpCS
		)
	)*;

// Rule AtomicExpression
ruleAtomicExpression:
	ruleLeftSubAtomicExpression (
		ruleInfixCompareOperatorName ruleRightSubAtomicExpression (
			ruleInfixOperatorName (
				rulePrimitiveLiteralExpCS
				| ruleAtomicExpression
			)
		)?
	)?;

// Rule LeftSubAtomicExpression
ruleLeftSubAtomicExpression:
	(ruleVariableExpCS | ruleCallExpCS);

// Rule RightSubAtomicExpression
ruleRightSubAtomicExpression:
	(ruleLiteralExpCS | ruleVariableExpCS | ruleCallExpCS);

// Rule InfixCompareOperatorName
ruleInfixCompareOperatorName:
	('>' | '<' | '>=' | '<=' | '=' | '<>');

// Rule InfixOperatorName
ruleInfixOperatorName: ( '*' | '/' | '+' | '-');

// Rule CallExpCS
ruleCallExpCS: ( ruleFeatureCallExpCS | ruleLoopExpCS);

// Rule LoopExpCS
ruleLoopExpCS: ruleIteratorExpCS;

// Rule IteratorExpCS
ruleIteratorExpCS:
	(
		(ruleClassiferCallExpCS | rulePropertyCallExpCS)
		| ruleSimpleNameCS
	) '->' ruleIteratorIdentifier '(' (
		ruleVariableDeclarationCS (',' ruleVariableDeclarationCS)* '|'
	)? (ruleLogicFormulaExpCS | ruleIfExpCS) ')';

// Rule IteratorIdentifier
ruleIteratorIdentifier:
	(
		'one'
		| 'exists'
		| 'select'
		| 'any'
		| 'forAll'
		| 'collect'
		| 'isUnique'
	);

// Rule ArgumentsCS
ruleArgumentsCS: ruleOCLExpressionCS ( ',' ruleArgumentsCS)?;

// Rule FeatureCallExpCS
ruleFeatureCallExpCS:
	(
		rulePropertyCallExpCS
		| ruleClassiferCallExpCS
		| ruleStandardOperationExpCS
		| ruleStandardNavigationCallExpCS
		| ruleOperationCallExpCS
	);

// Rule StandardNavigationCallExpCS
ruleStandardNavigationCallExpCS:
	(
		ruleClassiferCallExpCS
		| rulePropertyCallExpCS
		| ruleSimpleNameCS
	) '->' ruleStandardCollectionOperation;

// Rule StandardOperationExpCS
ruleStandardOperationExpCS:
	ruleVariableExpCS '.' (
		ruleVariableExpCS ruleIsMarkedPreCS? '.'
	)? rulePredefineOp;

// Rule PredefineOp
rulePredefineOp:
	(
		ruleStandardNoneParameterOperation
		| ruleStandardParameterOperation
		| ruleStandardDateOperation
	);

// Rule StandardNoneParameterOperation
ruleStandardNoneParameterOperation:
	(
		'oclIsNew()'
		| 'oclIsUndefined()'
		| 'isEmpty()'
		| 'notEmpty()'
		| 'oclIsInvaild()'
		| 'size()'
		| 'sum()'
	);

// Rule StandardParameterOperation
ruleStandardParameterOperation:
	'oclIsTypeOf' '(' (rulePrimitiveTypeCS | ruleEntityType) ')';

// Rule StandardCollectionOperation
ruleStandardCollectionOperation:
	('includes' | 'excludes' | 'includesAll' | 'excludesAll') '(' ruleSimpleNameCS ')';

// Rule StandardDateOperation
ruleStandardDateOperation:
	('After' | 'Before' | 'isAfter' | 'isBefore' | 'isEqual') '(' (
		ruleSimpleNameCS
		| ruleNumberLiteralExpCS
		| rulePropertyCallExpCS
	) ')' ('.' ruleStandardDateOperation)?;

// Rule ClassiferCallExpCS
ruleClassiferCallExpCS: ruleSimpleNameCS '.' 'allInstance()';

// Rule PropertyCallExpCS
rulePropertyCallExpCS:
	ruleVariableExpCS '.' (ruleVariableExpCS '.')? ruleSimpleNameCS ruleIsMarkedPreCS?;

// Rule OperationCallExpCS
ruleOperationCallExpCS:
	ruleSimpleNameCS '(' ruleOperationParameters? (
		',' ruleOperationParameters
	)* ')';

// Rule OperationParameters
ruleOperationParameters:
	(
		ruleSimpleNameCS
		| rulePropertyCallExpCS
		| (RULE_SINGLE_QUOTED_STRING | RULE_DOUBLE_QUOTED_STRING)
	);

// Rule IsMarkedPreCS
ruleIsMarkedPreCS: '@' 'pre';

// Rule VariableExpCS
ruleVariableExpCS: ( 'self' | 'result' | ruleSimpleNameCS);

// Rule SimpleNameCS
ruleSimpleNameCS: RULE_ID;

// Rule IfExpCS
ruleIfExpCS:
	'if' ruleOCLExpressionCS 'then' ruleOCLExpressionCS (
		'else' ruleOCLExpressionCS
	)? 'endif';

// Rule LetExpCS
ruleLetExpCS:
	'let' ruleVariableDeclarationCS (
		',' ruleVariableDeclarationCS
	)* 'in' ruleOCLExpressionCS;

// Rule VariableDeclarationCS
ruleVariableDeclarationCS:
	ruleSimpleNameCS (':' ruleTypeCS)? ('=' ruleOCLExpressionCS)?;

// Rule LiteralExpCS
ruleLiteralExpCS:
	(
		ruleCollectionLiteralExpCS
		| ruleTupleLiteralExpCS
		| rulePrimitiveLiteralExpCS
		| ruleEnumLiteralExpCS
	);

// Rule EnumLiteralExpCS
ruleEnumLiteralExpCS: ruleSimpleNameCS '::' RULE_ID;

// Rule TupleLiteralExpCS
ruleTupleLiteralExpCS:
	'Tuple' '{' ruleVariableDeclarationCS? (
		',' ruleVariableDeclarationCS
	)* '}';

// Rule CollectionTypeCS
ruleCollectionTypeCS:
	ruleCollectionTypeIdentifierCS '(' ruleTypeCS ')';

// Rule CollectionLiteralExpCS
ruleCollectionLiteralExpCS:
	ruleCollectionTypeIdentifierCS '{' ruleCollectionLiteralPartCS? (
		( ',') ruleCollectionLiteralPartCS
	)* '}';

// Rule CollectionLiteralPartCS
ruleCollectionLiteralPartCS:
	(ruleCollectionRangeCS | ( ruleCollectionItem));

// Rule CollectionRangeCS
ruleCollectionRangeCS:
	(ruleOCLExpressionCS) '..' ruleOCLExpressionCS;

// Rule CollectionItem
ruleCollectionItem: ruleOCLExpressionCS;

// Rule PrimitiveLiteralExpCS
rulePrimitiveLiteralExpCS:
	(
		ruleNumberLiteralExpCS
		| ruleStringLiteralExpCS
		| ruleBooleanLiteralExpCS
		| ruleInvalidLiteralExpCS
		| ruleNullLiteralExpCS
	);

// Rule NumberLiteralExpCS
ruleNumberLiteralExpCS:
	(
		ruleIntegerLiteralExpCS
		| ruleRealLiteralExpCS
		| ruleUnlimitedNaturalLiteralExpCS
	);

// Rule IntegerLiteralExpCS
ruleIntegerLiteralExpCS: RULE_INT;

// Rule RealLiteralExpCS
ruleRealLiteralExpCS: ruleFloat;

// Rule UnlimitedNaturalLiteralExpCS
ruleUnlimitedNaturalLiteralExpCS: '*';

// Rule BooleanLiteralExpCS
ruleBooleanLiteralExpCS: ( 'true' | 'false');

// Rule StringLiteralExpCS
ruleStringLiteralExpCS:
	(RULE_SINGLE_QUOTED_STRING | RULE_DOUBLE_QUOTED_STRING);

// Rule NullLiteralExpCS
ruleNullLiteralExpCS: 'null';

// Rule InvalidLiteralExpCS
ruleInvalidLiteralExpCS: 'invalid';

// Rule Float
ruleFloat: RULE_INT '.' RULE_INT;

// Rule CollectionTypeIdentifierCS
ruleCollectionTypeIdentifierCS:
	('Set' | 'Bag' | 'Sequence' | 'Collection' | 'OrderedSet');

// Rule PrimitiveTypeCS
rulePrimitiveTypeCS:
	(
		'Boolean'
		| 'Integer'
		| 'Real'
		| 'String'
		| 'UnlimitedNatural'
		| 'Date'
	);

// Rule OclTypeCS
ruleOclTypeCS: ( 'OclAny' | 'OclInvalid' | 'OclVoid');

// Rule AssociationTypeCS
ruleAssociationTypeCS:
	('Association' | 'Aggregation' | 'Composition');

RULE_DOUBLE_QUOTED_STRING:
	'"' (RULE_ESCAPED_CHARACTER | ~('\\' | '"' | '.'))* '"';

RULE_SINGLE_QUOTED_STRING:
	'\'' (RULE_ESCAPED_CHARACTER | ~('\\' | '\'' | '.'))* '\'';

fragment RULE_ESCAPED_CHARACTER:
	'\\' ('b' | 't' | 'n' | 'f' | 'r' | 'u' | '"' | '\'' | '\\');

RULE_ID:
	'^'? ('a' ..'z' | 'A' ..'Z' | '_') (
		'a' ..'z'
		| 'A' ..'Z'
		| '_'
		| '0' ..'9'
	)*;

RULE_INT: ('0' ..'9')+;

WS: [ \t\r\n]+ -> skip;

LINE_COMMENT: '//' ~[\r\n]* -> channel(1);
BLOCK_COMMENT: '/*' .*? '*/' -> channel(1);

Section guidance:
definition: Variables can be defined and can be used in the precondition or postcondition section. 
You should find the entity or entities you need for the next step and must set the proper value to it. 
The variable name `must be smallCamelCase`.
The variables are separate with a comma.
Note: the definition section is not required.
precondition: The contract of a system operation specifies the conditions that the state of the system is assumed to satisfy before the execution of the postcondition.
You should use the variables from the definition if provided or use the global variable from the context to check the conditions
postcondition: The conditions that the system state is required to satisfy after the execution (if it terminated), called the postcondition of the system operation. 
Typically, the precondition specifies the properties of the system state that need to be checked when system operation is to be executed, and the postcondition defines the possible changes that the execution of the system operation is to realize. 
The global variable can only be set value in postcondition

Transformation rules:
Here are transform rules
Rule1:
grammar: ```ClassName::Enumvalue```
description: ```retrive the enum value from the class which name is ClassName```
Rule2:
grammar: ```self.GlobalVariableName```
description: ```use the global variable in the Service or Module```
For `definition`, there 7 rules you need to know
Rule1:
grammar: ```obs:Set(ClassName) = ClassName.allInstance()```
description: ```find all instances of that ClassName and named the variable to obs```
Rule2:
grammar: ```obs:Set(ClassName) = ClassName.allInstance()->select(o | conditions(o))```
description: ```find all instances meet the conditions of that ClassName and named the variable to obs```
Rule3:
grammar: ```obs:ClassName = ClassName.allInstance()->any(o | conditions(o))```
description: ```find the first instance meet the conditions of that ClassName and named the variable to obs```
Rule4:
grammar: ```o:ClassName = ob.assoName```
description: ```find the linked object through assoName, where the multiplicity of the association may be one-to-one relationship and this will return an instance of ClassName reference named o to the object linked with object ob```
Rule5:
grammar: ```obs:Set(ClassName) = ob.assoName```
description: ```find the linked objects through assoName, where the multiplicity of the association may be one-to-many relationship and this will return instances of ClassName reference named obs to the object linked with object ob```
Rule6:
grammar: ```obs:Set(ClassName) = ob.assoName->select(o | conditions(o))```
description: ```find the linked objects through assoName and the conditions, where the multiplicity of the association may be one-to-many relationship and this will return instances of ClassName reference named obs to the object linked with object ob```
Rule7:
grammar: ```o:ClassName = ob.assoName```
description: ```find the linked object through assoName and the conditions, where the multiplicity of the association may be one-to-one relationship and this will return an instance of ClassName reference named o to the object linked with object ob```
For `precondition`, there 8 rules you need to know
Rule1:
grammar: ```ob.oclIsUndefined() = bool```
description: ```check that the reference ob does not refer to an object```
Rule2:
grammar: ```var.oclIsTypeOf(type)```
description: ```check that the variable var conforms the specific type, in which the var is a variable of primitive type, an object reference, or a reference list```
Rule3:
grammar: ```obs.isEmpty() = bool```
description: ```check the object list obs is empty```
Rule4:
grammar: ```obs.size() op mathExp```
description: ```op is the operator = or <> (euqal or not equal) or other infix comparison operator, the mathExp may contain numbers, variables, operators, functions, and brackets```
Rule5:
grammar: ```ob.AttriName op varPM```
description: ```op is the operator = or <> (euqal or not equal) or other infix comparison operators, and the AttriName is the attribute of the object ob, and the varPM is a variable of primitive type or a math expression```
Rule6:
grammar: ```ClassName.allInstance()->includes(ob)```
description: ```In the precondition section, this rule will check if the object ob is in the ClassName```
Rule7:
grammar: ```ClassName.allInstance()->excludes(ob)```
description: ```In the precondition section, this rule will check if the object ob isn't in the ClassName```
Rule8:
grammar: ```ClassName.allInstance()->isUnique(o:ClassName | o.AttriName)```
description: ```check the specific attribute AttriName has the unique value or not```
For `postcondition`, there 11 rules you need to know
Rule1:
grammar: ```let ob:ClassName in ob.oclIsNew()```
description: ```create a new empty object ob of the ClassName. The ob.oclIsNew() specifies that the object ob was created after the execution of system operation, this expression is always used as the first expression in postcondition, if needed to declare a new instance```
Rule2:
grammar: ```In the post condition, ClassName.allInstance()->includes(ob)```
description: ```Add the ob in the ClassName```
Rule3:
grammar: ```In the post condition, ClassName.allInstance()->excludes(ob)```
description: ```Delete the ob from the ClassName```
Rule4:
grammar: ```ob.assoName->includes(addOb)```
description: ```Add the addOb to the ClassName which ob.assoName belongs to```
Rule5:
grammar: ```ob.assoName->excludes(removeOb)```
description: ```Remove the removeOb from the ClassName which ob.assoName belongs to```
Rule6:
grammar: ```ob.assoName = addOb```
description: ```link the addOb to the ob.assoName```
Rule7:
grammar: ```ob.assoName = null```
description: ```remove the link from the ob.assoName```
Rule8:
grammar: ```ob.attriName = mathExp```
description: ```Set the attriName of the object ob of the value equals to the mathExp```
Rule9:
grammar: ```obs−>forAll(o:ClassName|o.AttriName=mathExp)```
description: ```Extension for Rule9. Specify the single object to objects```
Rule10:
grammar: ```result = var```
description: ```The variable named return equal to the variable var, this is the last statement in the post condition```
Rule11:
grammar: ```ThirdPartyServices.opName(vars)```
description: ```a special transformation rule that specifies the third-party application programming interface (APIs) such as cardPayment() and sorting() used in the postcondition```

Common mistakes to avoid:
```Please notice !!! ```
You are always generate the wrong code like ```result = a = b``` in postcondition, you should be careful about this, the right formula is ```a = b and result = a```
You are always generate the wrong code like ```result = (a = b)``` in postcondition, you should be careful about this, a=b should be declare in definition part like ```bool:Boolean = if a = b then true else false endif```
You are always generate the wrong code like ```c = (a = b)``` in postcondition, you should be careful about this, ```a = b``` should be declare in definition part like ```c:Boolean = if a = b then true else false endif```
You are always generate the wrong code like ```(expressionA) and (expressionB)```, you should be careful about this, you should just generate the code ```expressionA and expressionB```, don't abuse the usage of ```(``` or ```)```
You are always generate the wrong code like ```expressionA \n expressionB``` in definition part, it should be ```expressionA, expressionB```
You are always generate the wrong code with the keyword ```not```, there is no ```not``` keyword in g4 file
Collection ops includes(), excludes(), includesAll(), excludesAll() ONLY allow a single variable name inside parentheses (example: Staff.allInstance()->includes(staff)). Do NOT pass a nested expression such as Device.allInstance()->any(...) inside excludes(...). Instead bind in definition (example: dup:Device = Device.allInstance()->any(d:Device|d.Id=id)) then write dup.oclIsUndefined() = true in precondition, or use exists/any iterators allowed by the grammar.
You are always generate the wrong code to use the logic ```if``` to validate the condition in postcondition, the validation part should be in precondition

